const POPULAR_INDICES = [
    "NIFTY",
    "BANKNIFTY",
    "FINNIFTY",
    "MIDCPNIFTY",
    "SENSEX",
    "BANKEX",
    "INDIA VIX",
    "NIFTYNXT50"
];

export const FO_INDICES = [...new Map(RAW_FO_INDICES.map(item => [item.label, item])).values()].sort((a, b) => {
    const aIdx = POPULAR_INDICES.indexOf(a.label);
    const bIdx = POPULAR_INDICES.indexOf(b.label);
    if (aIdx !== -1 && bIdx !== -1) return aIdx - bIdx;
    if (aIdx !== -1) return -1;
    if (bIdx !== -1) return 1;
    return a.label.localeCompare(b.label);
});

